INSERT INTO `roll_event_landing_pages` (`id`, `event_id`, `slug`, `logo_image`, `hero_image`, `hero_slider_images`, `juknis_pdf`, `promo_image`, `hero_title`, `hero_subtitle`, `about_text`, `schedule_text`, `contact_whatsapp`, `contact_email`, `contact_instagram`, `theme_color`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 'indonesiarollerspeedseries', 'logo_1_1785823905.png', 'hero_1_1785570681.jpeg', '[\"hero_slide_1_1785585962_0.jpg\",\"hero_slide_1_1785585962_1.jpg\",\"hero_slide_1_1785585962_2.jpg\",\"hero_slide_1_1785585962_3.jpg\"]', NULL, 'promo_1_1786079664.png', 'Indonesia Roller Speed Series  ', 'The Biggest Roller Skating Competition in Indonesia', 'Indonesia Roller Speed (IRS) 2026 hadir dengan konsep kompetisi yang profesional dan berkelanjutan.\r\n1st Series: Velodrome Stadion Sultan Agung Bantul, Jogjakarta\r\n\r\n2nd Series:\r\n\r\n3rd Series:\r\n\r\n4th Series:\r\n\r\n5th Series:\r\n\r\nMengusung tema \"5 Kota, 1 Juara Nasional\", seri pertama kejuaraan nasional ini menargetkan 1.000 atlet terbaik dari seluruh Indonesia untuk bersaing memperebutkan total uang pembinaan total puluhan juta serta kesempatan bagi juara umum kelas Speed untuk diberangkatkan mengikuti kejuaraan tingkat internasional di luar negeri. Jangan lewatkan kesempatan menjadi bagian dari barometer sepatu roda speed Indonesia!\r\n', '', '+62-857-2572-2772', 'sportsentrytechsystem@gmail.com', 'https://www.instagram.com/indonesiarollerspeed/', '#fbc81f', 'Draft', '2026-08-01 07:32:07', '2026-09-19 06:02:50');
