INSERT INTO `roll_series` (`id`, `series_name`, `slug`, `hero_title`, `hero_subtitle`, `about_text`, `theme_color`, `status`, `logo_image`, `hero_slider_images`, `promo_image`, `show_standings`, `created_at`, `updated_at`, `sponsor_images`, `published_ku_standings`, `merchandise_images`, `merchandise_wa`, `point_rules`) VALUES
(1, 'Indonesia Roller Speed Series', 'indonesiarollerspeedseries', 'Indonesia Roller Speed Series  ', 'The Biggest Roller Skating Competition in Indonesia', 'Indonesia Roller Speed (IRS) 2026 hadir dengan konsep kompetisi yang profesional dan berkelanjutan.\r\n\r\n1st Series: Velodrome Stadion Sultan Agung Bantul, Jogjakarta\r\n\r\n2nd Series:\r\n\r\n3rd Series:\r\n\r\n4th Series:\r\n\r\n5th Series:\r\n\r\nMengusung tema \"5 Kota, 1 Juara Nasional\", seri pertama kejuaraan nasional ini menargetkan 1.000 atlet terbaik dari seluruh Indonesia untuk bersaing memperebutkan total uang pembinaan total puluhan juta serta kesempatan bagi juara umum kelas Speed untuk diberangkatkan mengikuti kejuaraan tingkat internasional di luar negeri. Jangan lewatkan kesempatan menjadi bagian dari barometer sepatu roda speed Indonesia!', '#fec702', 'Published', 'logo_1788700815_720.jpeg', '[\"slider_1788700815_8218.jpg\",\"slider_1788701174_2561.jpg\",\"slider_1788701318_4402.jpg\",\"slider_1788705119_9045.jpg\"]', 'promo_1788700815_514.jpg', 1, '2026-09-06 13:16:28', '2026-10-07 05:21:02', '[\"sponsor_1791103765_6117.jpeg\",\"sponsor_1791103765_9485.png\",\"sponsor_1791103765_2861.png\",\"sponsor_1791103765_5692.png\",\"sponsor_1791103765_5685.png\",\"sponsor_1791103765_8831.png\",\"sponsor_1791103765_3295.png\",\"sponsor_1791103765_8032.png\",\"sponsor_1791103765_8683.png\",\"sponsor_1791103765_8193.jpeg\",\"sponsor_1791103765_9748.png\",\"sponsor_1791103765_9346.png\",\"sponsor_1791103765_5471.png\",\"sponsor_1791103765_1656.png\",\"sponsor_1791103765_6881.png\",\"sponsor_1791336718_3458.png\",\"sponsor_1791336913_5952.png\"]', '[\"Speed - Junior\",\"Speed - Senior\",\"Speed - U 11\",\"Speed - U 14\",\"Speed - U 9\",\"Speed - U7\"]', '[\"merch_1788700815_3963.jpg\",\"merch_1788700815_9669.jpg\",\"merch_1788700815_1017.jpg\",\"merch_1788700815_7131.jpg\",\"merch_1788700815_2451.jpg\",\"merch_1788700815_9507.jpg\",\"merch_1788700815_6158.jpg\",\"merch_1788700815_3834.jpg\",\"merch_1788700815_4338.jpg\",\"merch_1788700815_1001.jpg\",\"merch_1788700815_6019.jpg\"]', '6285725722772', '{\"1\":\"12\",\"2\":\"9\",\"3\":\"7\",\"4\":\"5\",\"5\":\"4\",\"6\":\"3\",\"7\":\"2\",\"8\":\"1\"}');
